{
  "passageId": "diffusion-model-ai",
  "items": [
    {
      "id": "R1",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "확산 이미지의 형성에 쓰이는 ‘노이즈’라는 용어의 뜻을 불필요하거나 원하지 않는 값으로 규정한다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노이즈를 계속 더하는 작용이 원본을 알아볼 수 없는 노이즈 이미지로의 변화를 일으킨다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "노이즈를 더하여 원본을 알아볼 수 없게 되는 방향과 더해진 노이즈를 알아 원본을 복원하는 반대 방향을 대비한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "전체 작동 순서에서 언급한 순확산 과정의 절차와 학습 내용을 자세히 풀어 설명한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "전체 작동 순서에서 언급한 역확산 과정의 예측·제거·복원 절차를 구체적으로 설명한다."
    },
    {
      "id": "R6",
      "type": "PROCESS",
      "otherName": "",
      "reason": "노이즈 생성 단계의 산출물을 다음 단계에서 원본 이미지에 더하는 처리 순서이다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "원본 이미지에 노이즈를 더하는 연산이 노이즈가 포함된 확산 이미지를 만들어 낸다."
    },
    {
      "id": "R8",
      "type": "PROCESS",
      "otherName": "",
      "reason": "첫 단계에서 출력된 확산 이미지를 다음 단계의 입력으로 사용하는 순차적 처리 관계이다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "확산 이미지에 노이즈를 더하는 작업의 반복이 최종적인 노이즈 이미지를 만들어 낸다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노이즈의 특성이 단계마다 다르다는 사실이 단계별 이미지에서 특성을 추출하여 예측하는 방식을 설명하는 근거이다."
    },
    {
      "id": "R11",
      "type": "PROCESS",
      "otherName": "",
      "reason": "특성을 수치로 표현한 앞 단계의 산출물을 바탕으로 다음 단계의 노이즈 예측이 이루어진다."
    },
    {
      "id": "R12",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "노이즈의 특성을 표현하는 내부 수치들에 ‘잠재 표현’이라는 이름을 붙인다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "노이즈 예측기가 학습한다는 내용을 정답과 예측의 차이를 줄이는 구체적인 학습 방식으로 풀어 설명한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "정답과 출력의 차이를 줄인다는 지도 학습의 일반 원리를 노이즈 예측기의 학습에 적용한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "생성기가 넣은 노이즈가 정답이라는 사실이 그것과 예측된 노이즈의 차이를 줄이도록 학습하는 이유를 설명한다."
    },
    {
      "id": "R16",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "복원을 위해 더해진 노이즈를 알아야 한다는 요구에 대해 노이즈 예측기가 그 정보를 알아내는 장치로 제시된다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "순확산에서 학습된 노이즈 예측기를 이어지는 역확산 단계에서 사용하는 처리 순서이다."
    },
    {
      "id": "R18",
      "type": "OTHER",
      "otherName": "작동 방식의 공통성",
      "reason": "서로 다른 견해의 일치가 아니라 순확산과 역확산에서 예측기가 동일한 방식으로 작동한다는 공통성을 나타낸다."
    },
    {
      "id": "R19",
      "type": "PROCESS",
      "otherName": "",
      "reason": "이미지에서 잠재 표현을 구한 뒤 그 산출물을 바탕으로 노이즈를 예측하는 순서이다."
    },
    {
      "id": "R20",
      "type": "PROCESS",
      "otherName": "",
      "reason": "예측기가 산출한 노이즈를 다음 단계에서 이미지 연산기가 제거한다."
    },
    {
      "id": "R21",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노이즈를 예측하고 제거하는 작업의 반복이 노이즈를 대부분 없애 원본에 가까운 이미지를 남긴다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "노이즈를 추가하며 예측기를 학습시키는 순확산과 노이즈를 제거하며 이미지를 복원하는 역확산의 기능을 대비한다."
    },
    {
      "id": "R23",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "노이즈를 제거하여 이미지를 복원하는 역확산 방식을 원하는 이미지를 선택하여 생성하는 데 활용한다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "노이즈 특성을 수치로 나타내는 잠재 표현을 이미지 선택·혼합·생성에 활용한다."
    },
    {
      "id": "R25",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "잠재 표현을 조정하여 다른 특성의 노이즈를 만드는 것이 여러 이미지를 혼합하기 위한 수단으로 제시된다."
    },
    {
      "id": "R26",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "잠재 표현을 조정하여 다른 특성의 노이즈를 만드는 것이 실재하지 않는 이미지를 생성하는 수단으로 제시된다."
    }
  ]
}

